/// @namespace ProductCatalog
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model inventory {
  //----
  // COLUMNS
  //----
  /// Primary Key. Unique inventory record identifier.
  id String @id @db.Uuid

  /// Tracked variant's {@link product_variants.id}. Each inventory maps to exactly one variant.
  product_variant_id String @db.Uuid

  /// Current available quantity of the variant, stored as absolute number. No pre-calculation or aggregate fields (only most recent state, all log/events via catalog_event).
